for s in os.listdir('"'"'/proc'"'"'):
 if s.isdigit():
  try:
   v=open('"'"'/proc/'"'"'+s+'"'"'/cmdline'"'"','"'"'rb'"'"').read().replace(bytes([0]),b'"'"' '"'"').decode()
   if v.startswith('"'"'/opt/flyt/bin/flyt-shm-session-worker'"'"') or v.startswith('"'"'flyt-shm-session-worker --session'"'"'):out.append({'"'"'pid'"'"':int(s),'"'"'command'"'"':v})
  except (OSError,UnicodeError):pass
print(json.dumps(out))'

